// E2E 选择器策略：用稳定的 data-testid 而非易变的 CSS 路径
function findByTestId(dom, id) {
  return dom.find((el) => el["data-testid"] === id) ?? null;
}

const page = [
  { "data-testid": "submit-btn", text: "提交" },
  { "data-testid": "email-input", text: "" },
];

console.log(findByTestId(page, "submit-btn")?.text);
console.log(findByTestId(page, "email-input") !== null);
console.log(findByTestId(page, "missing") === null);
